from t4gpd.demos.AbstractGeoDataFrameDemos import AbstractGeoDataFrameDemos


class NantesBDT(AbstractGeoDataFrameDemos):
    '''
    classdocs
    '''

    @staticmethod
    def version():
        return "2025-06-15"

    @staticmethod
    def buildings(roi=None):
        buildings = NantesBDT.__buildings()
        if roi is not None:
            buildings = clip(buildings, roi, keep_geom_type=True)
        return buildings

