    @staticmethod
    def plot(oFile=None):
        import matplotlib.pyplot as plt

        buildings = NantesBDT.buildings()
        roads = NantesBDT.roads()

        # MAPPING
        fig, ax = plt.subplots(figsize=(1.7 * 8.26, 1 * 8.26))
        ax.set_title(NantesBDT.version(), size=24)
        buildings.plot(ax=ax, color="grey")
        roads.plot(ax=ax, color="black")
        ax.axis("off")
        if oFile is None:
            fig.tight_layout()
            plt.show()
        else:
            plt.savefig(oFile, bbox_inches="tight")
        plt.close(fig)


